def write(self, lines):
        lines = super().write(lines)
        # Find the separator line (the one with '=' characters) to place
        # at the top and bottom of the table.
        for i, line in enumerate(lines):
            if line and set(line) <= {"=", " "}:
                sep = line
                break
        else:
            sep = ""  # fallback, should not happen
        lines = [sep] + lines + [sep]
        return lines
